                cout << 0 << endl;
            } else {
                long long sum = 0;
                int size = s.size();

                if (size == 1) {
                    sum = s[0];
                } else if (size == 2) {
                    sum = (s[0] + s[1]) / 2;
                } else if (size == 3) {
