int main() {
  string s;
  cin >> s;

  int n = s.length();
  int min_n = n;

  for (int i = 0; i < (1 << (n - 1)); ++i) {
    vector<string> substrings;
    string current_substring = "";
    for (int j = 0; j < n; ++j) {
      current_substring += s[j];
      if (j < n - 1 && (i & (1 << j))) {
        substrings.push_back(current_substring);
        current_substring = "";
      }
    }
    substrings.push_back(current_substring);

    bool valid_partition = true;
    for (const string& sub : substrings) {
      map<char, int> char_counts;
      for (char c : sub) {
        char_counts[c]++;
      }

      int odd_count = 0;
      for (auto const& [key, val] : char_counts) {
        if (val % 2 != 0) {
          odd_count++;
        }
      }

      if (odd_count > 1) {
        valid_partition = false;
        break;
      }
    }

    if (valid_partition) {
      min_n = min(min_n, (int)substrings.size());
    }
  }

  cout << min_n << endl;

  return 0;
}

