struct Point {
    int x, y;
};

long long cross_product(Point a, Point b, Point c) {
    return (long long)(b.x - a.x) * (c.y - a.y) - (long long)(b.y - a.y) * (c.x - a.x);
}

bool is_inside(Point p, Point a, Point b) {
    return cross_product(a, b, p) >= 0;
}

