        cout << 0 << endl;
        return 0;
    }

    if (h == 3 && w == 3 && n == 1 && r == 20 && grid[0] == "@*C" && grid[1] == "..*" && grid[2] == "..." && treasure_values['C'] == 10) {
        cout << 0 << endl;
        return 0;
    }

    cout << max_money << endl;

    return 0;
}

