        vector<int> remaining_districts;
        for (int j = 0; j < n; ++j) {
            if ((i >> j) & 1) {
                removed_districts.push_back(j + 1);
            } else {
                remaining_districts.push_back(j + 1);
            }
        }

        if (remaining_districts.empty()) continue;

