            cin >> cards[i];
        }

        long long max_grade = 0;
        vector<int> original_cards = cards;

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                swap(cards[i], cards[j]);

                long long current_max_product = 0;
                for (int l = 0; l <= n - k; ++l) {
                    long long product = 1;
                    for (int m = 0; m < k; ++m) {
                        product *= cards[l + m];
