                    for (int m = 0; m < k; ++m) {
                        product *= original_cards[l + m];
                    }
                    original_max_product = max(original_max_product, product);
                }

                max_grade = max(max_grade, current_max_product - original_max_product);
                swap(cards[i], cards[j]);
            }
        }

        if (max_grade <= 0) {
            cout << "NO GAME" << endl;
